function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = () => setOn(o => !o);
  return [on, toggle];
}

function App() {
  const [open, toggleOpen] = useToggle(false);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={toggleOpen}>{open ? 'Hide' : 'Show'} details</button>
      {open && <p>Now you can see the details!</p>}
    </div>
  );
}

function useCounter(start = 0) {
  const [count, setCount] = useState(start);
  const inc = () => setCount(c => c + 1);
  return { count, inc };
}

function App() {
  const a = useCounter(0);
  const b = useCounter(100);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <p>A: {a.count} <button onClick={a.inc}>+1</button></p>
      <p>B: {b.count} <button onClick={b.inc}>+1</button></p>
    </div>
  );
}

function useDebounce(value, delay = 400) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}

function App() {
  const [text, setText] = useState('');
  const debounced = useDebounce(text, 500);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={text} onChange={e => setText(e.target.value)} placeholder="Search..." />
      <p>Live: {text}</p>
      <p>Debounced: {debounced}</p>
    </div>
  );
}

